mapper.select:
UPDATE act_hi_comment
SET MESSAGE_ = #{message},FULL_MSG_ =
    #{messageBlob,jdbcType=BLOB}
WHERE
    ID_ = #{commentId}

UPDATE act_hi_comment
SET USER_ID_ = #{user_id}
WHERE
    ID_ = #{commentId}

select *
        from (
               select a.MESSAGE_
               from act_hi_comment a
               where a.PROC_INST_ID_ = #{procInstId}
                 and a.TYPE_ = 'action' order by a.TIME_ desc
             )
        where rownum = 1
